# DK NVX.  Næstved Vest - Næstved Øst
#
let nn = path("d3.dk.nvx");

with detail = 4, railway = :first :pax :removed {
    with link = "line.dk.NVX" {
        track(
                nn[:nav + 0.9dl, :nav + 1dl]
            ..  nn[:nas.xr - 300m, :nas.xr - 1seg] << 1mo
        );
        track(:ror, nn[:nas.xr - 1.01seg, :nas.xr] << 1mo);
        track(:ror, nn[:nas.xr, :nao - 1dl] << 1mo);
    }
}

